def bucket_unique(keys, bucket_count):
    buckets = []
    for _ in range(bucket_count):
        buckets.append([])
    seen = set()
    for key in keys:
        if key not in seen:
            buckets[key % bucket_count].append(key)
            seen.add(key)
    return buckets

print(bucket_unique([1, 5, 1, 2], 4))
print(bucket_unique([], 2))
print(bucket_unique([0, 4, 8], 4))

def locate_key(buckets, key):
    comparisons = 0
    for stored in buckets[key % len(buckets)]:
        comparisons += 1
        if stored == key:
            return True, comparisons
    return False, comparisons

print(locate_key([[], [1, 5], [], []], 5))
print(locate_key([[], [1, 5], [], []], 9))
print(locate_key([[], []], 0))

def colliding_positions(keys, bucket_count):
    result = []
    for first in range(len(keys)):
        for second in range(first + 1, len(keys)):
            if keys[first] != keys[second] and keys[first] % bucket_count == keys[second] % bucket_count:
                result.append((first, second))
    return result

print(colliding_positions([1, 5, 2], 4))
print(colliding_positions([1, 1, 5], 4))
print(colliding_positions([], 3))
